<script lang="ts">
  import { expedition } from '../stores/expedition.svelte.ts';
  import ExpeditionAvailableContent from './expedition/ExpeditionAvailableContent.svelte';
  import ExpeditionActiveContent from './expedition/ExpeditionActiveContent.svelte';
  import { onMount } from 'svelte';
  import { facade } from '@bus/facade';
  import { playGameSfx } from '../audio/audioDirector.ts';

  let snap = $derived(expedition.snapshot);
  let ui = $derived(snap.ui);
  let slotClock = $state(0);
  let slotBaseline = { ms: -1, at: 0 };

  onMount(() => {
    const id = setInterval(() => {
      slotClock += 1;
    }, 1000);
    return () => clearInterval(id);
  });

  const slotsAreFull = $derived(
    (snap.activeCount ?? 0) > 0 && (snap.activeCount ?? 0) >= (snap.maxSlots ?? 0),
  );
  const nextSlotRemaining = $derived.by(() => {
    void slotClock;
    const waiting = slotsAreFull && (snap.completedCount ?? 0) === 0;
    const ms = snap.nextCompletionRemainingMs;
    if (!waiting || ms == null || ms <= 0) return null;
    if (slotBaseline.ms !== ms) slotBaseline = { ms, at: Date.now() };
    return Math.max(0, ms - (Date.now() - slotBaseline.at));
  });
  const showNextSlot = $derived(nextSlotRemaining != null && nextSlotRemaining > 0);

  function formatTimeShort(ms: number | null | undefined): string {
    if (ms == null || ms <= 0) return '';
    const totalSec = Math.max(0, Math.ceil(ms / 1000));
    const m = Math.floor(totalSec / 60);
    const s = totalSec % 60;
    const pad = (n: number) => String(n).padStart(2, '0');
    return `${pad(m)}:${pad(s)}`;
  }

  function formatCountdown(ms: number | null | undefined): string {
    if (ms == null || ms <= 0) return '00:00';
    const totalSec = Math.max(0, Math.ceil(ms / 1000));
    const h = Math.floor(totalSec / 3600);
    const m = Math.floor((totalSec % 3600) / 60);
    const s = totalSec % 60;
    const pad = (n: number) => String(n).padStart(2, '0');
    return h > 0 ? `${pad(h)}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
  }

  function handleAutoRelaunchToggle(e: Event) {
    const checked = (e.currentTarget as HTMLInputElement).checked;
    playGameSfx('click');
    facade.dispatch({ type: 'TOGGLE_AUTO_EXPEDITION_RELAUNCH', enabled: checked });
  }
</script>

<!-- Cible = #expeditionsTab -->
<div class="expedition-top-bar">
  <div class="expedition-top-left">
    <div class="expedition-slot-pips" title="Slots d'expédition">
      {#each (snap.slotPips ?? []) as pip, i (i)}
        <span class="expedition-slot-pip is-{pip}" title="Slot {i + 1} : {pip === 'done' ? (ui.language === 'en' ? 'To claim' : 'À récupérer') : (pip === 'running' ? (ui.language === 'en' ? 'In progress' : 'En cours') : (ui.language === 'en' ? 'Free' : 'Libre'))}"></span>
      {/each}
    </div>
    <span class="expedition-slots">
      <span id="expeditionsSlotsLabel">{ui.slotsPrefix}</span>
      <strong id="expeditionSlots">{snap.slotsLabel}</strong>
    </span>
    {#if showNextSlot}
      <span class="expedition-next-slot">
        {ui.language === 'en' ? 'Next in' : 'Prochain dans'} {formatCountdown(nextSlotRemaining)}
      </span>
    {/if}
    {#if (snap.completedCount ?? 0) > 0}
      <span class="expedition-sub-status is-ready">({snap.completedCount} {ui.language === 'en' ? 'to claim' : 'à récupérer'})</span>
    {/if}
  </div>

  <div class="expedition-top-right">
    {#if snap.autoRelaunchUnlocked}
      <label class="retro-toggle expedition-auto-toggle" title={ui.autoRelaunchTooltip}>
        <input
          type="checkbox"
          checked={snap.autoRelaunchEnabled !== false}
          onchange={handleAutoRelaunchToggle}
        />
        <span class="retro-toggle__track"><span class="retro-toggle__thumb"></span></span>
        <span>{ui.autoRelaunchLabel}</span>
      </label>
    {/if}
    <button type="button" class="expedition-mastery-btn" data-action="showMasteryModal">
      <span id="expeditionsMasteryLabel">🧭 {ui.masteryLabel}</span>
    </button>
  </div>
</div>

<!-- Section 1 : En cours (prioritaire, en haut) -->
<div class="expedition-section-header">
  <h4 id="expeditionsRunningLabel" class="expedition-section-title">
    {ui.runningTitle}
    <span class="expedition-section-count">({snap.slotsLabel})</span>
  </h4>

  {#if (snap.completedCount ?? 0) > 0}
    <div class="expedition-section-actions">
      <button type="button" class="expedition-claim-all-btn" data-action="claimAllExpeditions">
        Tout récupérer ({snap.completedCount})
      </button>
      <button type="button" class="expedition-relaunch-all-btn" data-action="claimAndRelaunchAllExpeditions" title="Récupérer le butin et relancer les mêmes équipes">
        ↻ Tout relancer ({snap.completedCount})
      </button>
    </div>
  {/if}
</div>
<ExpeditionActiveContent />

<hr class="expedition-divider">

<!-- Section 2 : Missions Disponibles (en dessous) -->
<div class="expedition-section-header">
  <h4 id="expeditionsAvailableLabel" class="expedition-section-title">
    {ui.availableTitle}
    <span class="expedition-section-count">
      ({snap.boardCount ?? 0}/{snap.boardMax ?? 6}{#if (snap.boardCount ?? 0) < (snap.boardMax ?? 6) && snap.nextMissionTimerMs != null && snap.nextMissionTimerMs > 0} · Prochaine dans {formatTimeShort(snap.nextMissionTimerMs)}{/if})
    </span>
  </h4>
</div>
<ExpeditionAvailableContent />
